// 已登录状态下，查路由表找到 pubAllotNotice 详情页路径，并打开一个已有单据验证字段
import { chromium } from 'playwright'
import { writeFileSync } from 'node:fs'

const SITE = 'http://127.0.0.1:8119'
const TMP = 'C:/Users/Administrator/AppData/Local/Temp/'
const EXEC = 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'

const browser = await chromium.launch({ headless: true, executablePath: EXEC })
const ctx = await browser.newContext({ viewport: { width: 1700, height: 1050 }, storageState: TMP + 'v_state.json' })
const page = await ctx.newPage()

await page.goto(SITE + '/login#/index', { waitUntil: 'networkidle', timeout: 90000 })
await page.waitForTimeout(4000)

// 在页面里读路由表
const routes = await page.evaluate(() => {
  const app = document.querySelector('#app')
  const vm = app && app.__vue__
  const all = vm && vm.$router ? vm.$router.getRoutes() : []
  return all
    .filter((r) => (r.meta && String(r.meta.filePath || '').includes('pubAllotNotice')) || String(r.path).includes('allot'))
    .map((r) => ({ path: r.path, filePath: r.meta && r.meta.filePath, name: r.name }))
})
console.log('ROUTES', JSON.stringify(routes, null, 2))
writeFileSync(TMP + 'v_routes.json', JSON.stringify(routes, null, 2))
await browser.close()

